//! Which reflected `bool` properties are real `bool`s and which are bitfields.
//!
//! `CanSerializeAsZero` gates a `BoolProperty` on `IsNativeBool()`
//! (UnversionedPropertySerialization.cpp:189): a real `bool` may be zero-masked,
//! a bitfield `uint8 bFoo : 1` may not. Masking a bitfield is not a cosmetic
//! difference — `LoadZero` memzeroes the property's storage, which would clear
//! every sibling bit sharing that byte.
//!
//! The `.usmap` cannot tell them apart; both arrive as `EPropertyType::BoolProperty`.
//! The distinction only exists in the C++ declaration, so this table is
//! extracted from the shipped `UHTHeaderDump` — the game's own generated
//! headers, not a guess at what upstream Unreal declares.
//!
//! Keyed by *declaring* struct, not by the class a property flattens into: 133
//! bool property names are declared both ways by different structs, so a
//! name-only table would be wrong for them. Unknown entries answer `false`,
//! which is the safe direction — it writes the value longhand rather than
//! risking a mask that clears sibling bits.

/// `(declaring struct, property)` pairs declared as a real `bool`.
