/// Whether `struct_name::property` is a real `bool`, and so may be zero-masked.
///
/// `false` for anything not in the table, deliberately: an unknown declaration
/// must not be masked.
pub fn is_native_bool(struct_name: &str, property: &str) -> bool {
    NATIVE_BOOLS.binary_search(&(struct_name, property)).is_ok()
}

/// Whether the dump declares `struct_name::property` at all, either way.
///
/// Lets a caller distinguish "known to be a bitfield" from "never seen", which
/// [`is_native_bool`] deliberately collapses.
pub fn bool_is_known(struct_name: &str, property: &str) -> bool {
    NATIVE_BOOLS.binary_search(&(struct_name, property)).is_ok()
        || BITFIELD_BOOLS.binary_search(&(struct_name, property)).is_ok()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tables_are_sorted_for_binary_search() {
        assert!(NATIVE_BOOLS.windows(2).all(|w| w[0] < w[1]), "NATIVE_BOOLS must be sorted");
        assert!(BITFIELD_BOOLS.windows(2).all(|w| w[0] < w[1]), "BITFIELD_BOOLS must be sorted");
    }

    /// The two halves are a partition: a property is declared one way or the
    /// other, never both.
    #[test]
    fn no_property_is_declared_both_ways() {
        for k in NATIVE_BOOLS {
            assert!(BITFIELD_BOOLS.binary_search(k).is_err(), "{k:?} declared both ways");
        }
    }

    #[test]
    fn known_declarations_classify() {
        // `bEnabled` is declared both ways in this very dump — a plain `bool` on
        // `FStateTreeDebugTextTask`, a `: 1` bitfield on `UPostProcessComponent`
        // and `USkyLight`. It is the concrete reason the key is the declaring
        // struct rather than the property name.
        assert!(is_native_bool("StateTreeDebugTextTask", "bEnabled"));
        assert!(!is_native_bool("PostProcessComponent", "bEnabled"));
        assert!(bool_is_known("PostProcessComponent", "bEnabled"));

        // Absent entirely, so `is_native_bool` answers `false` for the safe
        // reason rather than the measured one — which is what `bool_is_known`
        // is there to tell apart.
        assert!(!is_native_bool("PrimitiveComponent", "NotAProperty"));
        assert!(!bool_is_known("PrimitiveComponent", "NotAProperty"));
    }
}
